---@meta

---@class EnmityProperties
---@field ce integer -- Cumulative Enmity generated by action
---@field ve integer -- Volatile Enmity generated by action

---@class SkillchainProperties
---@field primary? xi.skillchainType
---@field secondary? xi.skillchainType
---@field tertiary? xi.skillchainType

---@class Action
---@field animation integer -- Animation ID of the action
---@field message? xi.basic -- Message ID of the action
---@field enmity? EnmityProperties -- Enmity values for the action, if any
---@field skillchain? SkillchainProperties -- Skillchain properties for the action, if any
---@field knockback? xi.action.knockback -- Knockback value upon completion of action
---@field target xi.target[] -- List of valid target types for the action
---@field range? integer -- Max distance at which the target can be for the action to start/complete
---@field aoe? AoEProperties -- AoE properties, if any.
